from django.contrib.sitemaps.views import sitemap
from django.contrib.sitemaps import Sitemap
from django.http import Http404, HttpResponseForbidden
from .models import ClientInvoice, TenantOrganization

class DynamicTenantInvoiceSitemap(Sitemap):
    def __init__(self, tenant):
        self.tenant = tenant

    def items(self):
        return ClientInvoice.objects.filter(tenant=self.tenant)

    def location(self, item):
        return f"/invoices/{item.invoice_token}/download/"

def tenant_invoice_sitemap_view(request, tenant_slug):
    if not request.user.is_authenticated:
        return HttpResponseForbidden('Authentication required')

    try:
        tenant = TenantOrganization.objects.get(slug=tenant_slug)
    except TenantOrganization.DoesNotExist:
        raise Http404('Tenant not found')

    # Ensure only authorized tenant administrators can generate this sitemap
    if request.user.organization_id != tenant.id or not request.user.is_admin:
        return HttpResponseForbidden('Access denied to tenant invoice sitemap')

    sitemaps = {'invoices': DynamicTenantInvoiceSitemap(tenant)}
    return sitemap(request, sitemaps)
